import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

// AES-256-GCM for cfo.ai tokens at rest. Key: CFO_TOKEN_KEY, 32 bytes as base64 or hex
// (generate with `openssl rand -base64 32`). Ciphertext format: "v1:" + base64(iv | tag | data).
// The user id is bound as AAD, so a row copied to another user does not decrypt.

const VERSION = "v1";
const IV_BYTES = 12;
const TAG_BYTES = 16;

// Parse CFO_TOKEN_KEY; throws with a message that never includes the key itself.
export function loadTokenKey(raw = process.env.CFO_TOKEN_KEY): Buffer {
  const value = raw?.trim();
  if (!value) throw new Error("CFO_TOKEN_KEY is not set");
  const key = /^[0-9a-fA-F]{64}$/.test(value) ? Buffer.from(value, "hex") : Buffer.from(value, "base64");
  if (key.length !== 32) throw new Error("CFO_TOKEN_KEY must be 32 bytes (base64 or hex)");
  return key;
}

export function encryptToken(plain: string, aad: string, key = loadTokenKey()): string {
  const iv = randomBytes(IV_BYTES);
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  cipher.setAAD(Buffer.from(aad, "utf8"));
  const data = Buffer.concat([cipher.update(plain, "utf8"), cipher.final()]);
  return `${VERSION}:${Buffer.concat([iv, cipher.getAuthTag(), data]).toString("base64")}`;
}

export function decryptToken(encoded: string, aad: string, key = loadTokenKey()): string {
  const [version, payload] = encoded.split(":", 2);
  if (version !== VERSION || !payload) throw new Error("Unsupported token ciphertext");
  const raw = Buffer.from(payload, "base64");
  if (raw.length < IV_BYTES + TAG_BYTES) throw new Error("Truncated token ciphertext");
  const decipher = createDecipheriv("aes-256-gcm", key, raw.subarray(0, IV_BYTES));
  decipher.setAAD(Buffer.from(aad, "utf8"));
  decipher.setAuthTag(raw.subarray(IV_BYTES, IV_BYTES + TAG_BYTES));
  return Buffer.concat([decipher.update(raw.subarray(IV_BYTES + TAG_BYTES)), decipher.final()]).toString("utf8");
}
import { createHash, randomBytes } from "node:crypto";
import { decryptToken, encryptToken, loadTokenKey } from "./crypto";
import {
  PENDING_TTL_MS,
  deleteConnection,
  deletePending,
  getConnection,
  getPending,
  savePending,
  upsertConnection,
} from "./store";

// Per-user OAuth 2.1 (authorization code + PKCE S256) against cfo.ai's authorization server,
// done with plain fetch: discovery -> authorize URL -> code exchange -> refresh.

export const CFO_MCP_URL = "https://api.cfo.ai/mcp";
const RESOURCE_METADATA_URL = "https://api.cfo.ai/.well-known/oauth-protected-resource/mcp";
export const CFO_SCOPES = "openid profile email offline_access";
const DISCOVERY_TTL_MS = 60 * 60 * 1000;
const REFRESH_SKEW_MS = 60 * 1000;
const DEFAULT_TTL_S = 3600;

export type AuthServerMetadata = {
  issuer: string;
  authorization_endpoint: string;
  token_endpoint: string;
  registration_endpoint?: string;
  code_challenge_methods_supported?: string[];
};

export type CfoDiscovery = { resource: string; authServer: AuthServerMetadata };

type TokenResponse = {
  access_token: string;
  token_type?: string;
  expires_in?: number;
  refresh_token?: string;
  scope?: string;
};

export class CfoOAuthError extends Error {
  constructor(public readonly code: string, message: string) {
    super(message);
    this.name = "CfoOAuthError";
  }
}

// Public origin used for the redirect URI (APP_URL, else BETTER_AUTH_URL).
export function appBaseUrl(): string {
  return (process.env.APP_URL ?? process.env.BETTER_AUTH_URL ?? "http://localhost:3000").replace(/\/+$/, "");
}

export function cfoRedirectUri(): string {
  return `${appBaseUrl()}/api/cfo/callback`;
}

// Reason the connection cannot be used, or null when CFO_OAUTH_CLIENT_ID and CFO_TOKEN_KEY are valid.
export function cfoConfigError(): string | null {
  if (!process.env.CFO_OAUTH_CLIENT_ID?.trim()) return "CFO_OAUTH_CLIENT_ID is not set (run `npm run cfo:register`)";
  try {
    loadTokenKey();
  } catch (error: unknown) {
    return (error as Error).message;
  }
  return null;
}

function clientId(): string {
  const id = process.env.CFO_OAUTH_CLIENT_ID?.trim();
  if (!id) throw new CfoOAuthError("not_configured", "CFO_OAUTH_CLIENT_ID is not set");
  return id;
}

async function getJson(url: string): Promise<Record<string, unknown>> {
  const res = await fetch(url, { headers: { accept: "application/json" } });
  if (!res.ok) throw new CfoOAuthError("discovery_failed", `GET ${url} returned ${res.status}`);
  return (await res.json()) as Record<string, unknown>;
}

// RFC 8414 well-known URL, inserting the issuer path after the well-known segment.
function wellKnown(issuer: string, suffix: string): string {
  const u = new URL(issuer);
  const path = u.pathname.replace(/\/+$/, "");
  return `${u.origin}/.well-known/${suffix}${path}`;
}

let discoveryCache: { at: number; value: Promise<CfoDiscovery> } | null = null;

// Protected resource metadata (RFC 9728) -> authorization server metadata (RFC 8414 / OIDC).
export function discoverCfo(): Promise<CfoDiscovery> {
  if (discoveryCache && Date.now() - discoveryCache.at < DISCOVERY_TTL_MS) return discoveryCache.value;
  const value = (async () => {
    const prm = await getJson(RESOURCE_METADATA_URL);
    const resource = typeof prm.resource === "string" ? prm.resource : CFO_MCP_URL;
    const servers = prm.authorization_servers;
    if (!Array.isArray(servers) || typeof servers[0] !== "string") {
      throw new CfoOAuthError("discovery_failed", "No authorization server in cfo.ai resource metadata");
    }
    const issuer = servers[0];
    let meta: Record<string, unknown>;
    try {
      meta = await getJson(wellKnown(issuer, "oauth-authorization-server"));
    } catch {
      meta = await getJson(wellKnown(issuer, "openid-configuration"));
    }
    if (typeof meta.authorization_endpoint !== "string" || typeof meta.token_endpoint !== "string") {
      throw new CfoOAuthError("discovery_failed", "Authorization server metadata is missing endpoints");
    }
    const methods = meta.code_challenge_methods_supported;
    if (Array.isArray(methods) && !methods.includes("S256")) {
      throw new CfoOAuthError("discovery_failed", "Authorization server does not support PKCE S256");
    }
    return { resource, authServer: { ...(meta as AuthServerMetadata), issuer: (meta.issuer as string) ?? issuer } };
  })();
  discoveryCache = { at: Date.now(), value };
  value.catch(() => {
    if (discoveryCache?.value === value) discoveryCache = null;
  });
  return value;
}

const b64url = (buf: Buffer) => buf.toString("base64url");

export function pkcePair(): { verifier: string; challenge: string } {
  const verifier = b64url(randomBytes(32));
  return { verifier, challenge: b64url(createHash("sha256").update(verifier).digest()) };
}

// Pure URL builder (exported for tests).
export function buildAuthorizeUrl(
  authorizationEndpoint: string,
  p: { clientId: string; redirectUri: string; state: string; challenge: string; resource: string; scope: string },
): string {
  const url = new URL(authorizationEndpoint);
  url.searchParams.set("response_type", "code");
  url.searchParams.set("client_id", p.clientId);
  url.searchParams.set("redirect_uri", p.redirectUri);
  url.searchParams.set("scope", p.scope);
  url.searchParams.set("state", p.state);
  url.searchParams.set("code_challenge", p.challenge);
  url.searchParams.set("code_challenge_method", "S256");
  url.searchParams.set("resource", p.resource);
  return url.toString();
}

// Create a user-bound pending state + PKCE verifier and return the authorize URL to redirect to.
export async function startCfoAuthorization(userId: string): Promise<string> {
  const cid = clientId();
  const key = loadTokenKey();
  const { resource, authServer } = await discoverCfo();
  const state = b64url(randomBytes(32));
  const { verifier, challenge } = pkcePair();
  savePending({
    state,
    user_id: userId,
    code_verifier_enc: encryptToken(verifier, `pending:${state}`, key),
    created_at: Date.now(),
  });
  return buildAuthorizeUrl(authServer.authorization_endpoint, {
    clientId: cid,
    redirectUri: cfoRedirectUri(),
    state,
    challenge,
    resource,
    scope: CFO_SCOPES,
  });
}

// Validate and consume a pending state for this user; returns the PKCE verifier.
export function consumePendingState(userId: string, state: string, now = Date.now()): string {
  const row = getPending(state);
  if (!row) throw new CfoOAuthError("invalid_state", "Unknown or already used OAuth state");
  if (row.user_id !== userId) throw new CfoOAuthError("state_user_mismatch", "OAuth state belongs to another user");
  deletePending(state);
  if (now - row.created_at > PENDING_TTL_MS) throw new CfoOAuthError("state_expired", "OAuth state expired");
  return decryptToken(row.code_verifier_enc, `pending:${state}`);
}

// Read claims from a JWT access token without verifying it (informational only: exp, org_id).
function jwtClaims(token: string): Record<string, unknown> {
  const parts = token.split(".");
  if (parts.length !== 3) return {};
  try {
    return JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8")) as Record<string, unknown>;
  } catch {
    return {};
  }
}

async function postToken(tokenEndpoint: string, body: Record<string, string>): Promise<TokenResponse> {
  const res = await fetch(tokenEndpoint, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded", accept: "application/json" },
    body: new URLSearchParams(body),
  });
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  if (!res.ok || typeof json.access_token !== "string") {
    // Only the standard error code is surfaced; descriptions and bodies may echo inputs.
    const code = typeof json.error === "string" ? json.error : `http_${res.status}`;
    throw new CfoOAuthError(code, `Token endpoint returned ${res.status} (${code})`);
  }
  return json as unknown as TokenResponse;
}

function persistTokens(userId: string, tokens: TokenResponse, previousRefreshEnc: string | null): void {
  const key = loadTokenKey();
  const claims = jwtClaims(tokens.access_token);
  const expiresAt =
    typeof tokens.expires_in === "number"
      ? Date.now() + tokens.expires_in * 1000
      : typeof claims.exp === "number"
        ? claims.exp * 1000
        : Date.now() + DEFAULT_TTL_S * 1000;
  upsertConnection({
    user_id: userId,
    access_token_enc: encryptToken(tokens.access_token, `access:${userId}`, key),
    // Keep the old refresh token when the server does not rotate it.
    refresh_token_enc: tokens.refresh_token
      ? encryptToken(tokens.refresh_token, `refresh:${userId}`, key)
      : previousRefreshEnc,
    expires_at: expiresAt,
    scope: tokens.scope ?? null,
    org_id: typeof claims.org_id === "string" ? claims.org_id : null,
  });
}

// Handle the redirect back from the authorization server for the signed-in user.
export async function completeCfoAuthorization(userId: string, params: URLSearchParams): Promise<void> {
  const state = params.get("state");
  if (!state) throw new CfoOAuthError("missing_state", "Callback has no state");
  const verifier = consumePendingState(userId, state);
  const { resource, authServer } = await discoverCfo();
  const iss = params.get("iss");
  if (iss && iss !== authServer.issuer) throw new CfoOAuthError("issuer_mismatch", "Callback issuer does not match");
  const error = params.get("error");
  if (error) throw new CfoOAuthError(error, `Authorization failed (${error})`);
  const code = params.get("code");
  if (!code) throw new CfoOAuthError("missing_code", "Callback has no code");
  const tokens = await postToken(authServer.token_endpoint, {
    grant_type: "authorization_code",
    code,
    redirect_uri: cfoRedirectUri(),
    client_id: clientId(),
    code_verifier: verifier,
    resource,
  });
  persistTokens(userId, tokens, null);
}

export function getCfoStatus(userId: string): { connected: boolean; expiresAt?: string } {
  const row = getConnection(userId);
  if (!row) return { connected: false };
  return { connected: true, expiresAt: new Date(row.expires_at).toISOString() };
}

export function disconnectCfo(userId: string): boolean {
  return deleteConnection(userId);
}

const refreshing = new Map<string, Promise<string | null>>();

async function refreshAccessToken(userId: string): Promise<string | null> {
  const row = getConnection(userId);
  if (!row?.refresh_token_enc) return null;
  try {
    const refreshToken = decryptToken(row.refresh_token_enc, `refresh:${userId}`);
    const { resource, authServer } = await discoverCfo();
    const tokens = await postToken(authServer.token_endpoint, {
      grant_type: "refresh_token",
      refresh_token: refreshToken,
      client_id: clientId(),
      resource,
    });
    persistTokens(userId, tokens, row.refresh_token_enc);
    return tokens.access_token;
  } catch (error: unknown) {
    const code = error instanceof CfoOAuthError ? error.code : "refresh_error";
    console.warn(`cfo.ai token refresh failed for user ${userId}: ${code}`);
    // A rejected refresh token will never work again; drop the connection so status shows disconnected.
    if (code === "invalid_grant") deleteConnection(userId);
    return null;
  }
}

// A valid access token for this user (refreshed when it expires within 60s), or null if not connected
// or the refresh fails. Concurrent callers share one refresh so a rotated refresh token is used once.
export async function getCfoAccessToken(userId: string): Promise<string | null> {
  if (cfoConfigError()) return null;
  const row = getConnection(userId);
  if (!row) return null;
  if (row.expires_at - Date.now() > REFRESH_SKEW_MS) {
    try {
      return decryptToken(row.access_token_enc, `access:${userId}`);
    } catch {
      console.warn(`cfo.ai access token for user ${userId} could not be decrypted`);
      return null;
    }
  }
  let pending = refreshing.get(userId);
  if (!pending) {
    pending = refreshAccessToken(userId).finally(() => refreshing.delete(userId));
    refreshing.set(userId, pending);
  }
  return pending;
}
import { resolve } from "node:path";
import Database from "better-sqlite3";
import { dataDir } from "../data-dir";

// Per-user cfo.ai OAuth state in data/auth.db (own connection, same file as Better Auth).
// Token and verifier columns hold AES-GCM ciphertext from ./crypto, never plaintext.

export const PENDING_TTL_MS = 10 * 60 * 1000;

export type CfoConnectionRow = {
  user_id: string;
  access_token_enc: string;
  refresh_token_enc: string | null;
  expires_at: number; // epoch ms
  scope: string | null;
  org_id: string | null;
  created_at: number;
  updated_at: number;
};

export type CfoPendingRow = {
  state: string;
  user_id: string;
  code_verifier_enc: string;
  created_at: number;
};

let db: Database.Database | null = null;

// Open the database and create tables idempotently; safe to call repeatedly.
export function cfoDb(): Database.Database {
  if (db) return db;
  const conn = new Database(resolve(dataDir(), "auth.db"));
  conn.pragma("busy_timeout = 5000");
  conn.exec(`
    CREATE TABLE IF NOT EXISTS cfo_connections (
      user_id TEXT PRIMARY KEY,
      access_token_enc TEXT NOT NULL,
      refresh_token_enc TEXT,
      expires_at INTEGER NOT NULL,
      scope TEXT,
      org_id TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS cfo_oauth_pending (
      state TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      code_verifier_enc TEXT NOT NULL,
      created_at INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS cfo_oauth_pending_created_at ON cfo_oauth_pending (created_at);
  `);
  db = conn;
  return conn;
}

export function savePending(row: CfoPendingRow): void {
  const conn = cfoDb();
  conn.prepare("DELETE FROM cfo_oauth_pending WHERE created_at < ?").run(Date.now() - PENDING_TTL_MS);
  conn
    .prepare("INSERT INTO cfo_oauth_pending (state, user_id, code_verifier_enc, created_at) VALUES (?, ?, ?, ?)")
    .run(row.state, row.user_id, row.code_verifier_enc, row.created_at);
}

export function getPending(state: string): CfoPendingRow | undefined {
  return cfoDb().prepare("SELECT * FROM cfo_oauth_pending WHERE state = ?").get(state) as CfoPendingRow | undefined;
}

export function deletePending(state: string): void {
  cfoDb().prepare("DELETE FROM cfo_oauth_pending WHERE state = ?").run(state);
}

export function getConnection(userId: string): CfoConnectionRow | undefined {
  return cfoDb().prepare("SELECT * FROM cfo_connections WHERE user_id = ?").get(userId) as CfoConnectionRow | undefined;
}

export function upsertConnection(row: Omit<CfoConnectionRow, "created_at" | "updated_at">): void {
  const now = Date.now();
  cfoDb()
    .prepare(
      `INSERT INTO cfo_connections (user_id, access_token_enc, refresh_token_enc, expires_at, scope, org_id, created_at, updated_at)
       VALUES (@user_id, @access_token_enc, @refresh_token_enc, @expires_at, @scope, @org_id, @now, @now)
       ON CONFLICT(user_id) DO UPDATE SET
         access_token_enc = excluded.access_token_enc,
         refresh_token_enc = excluded.refresh_token_enc,
         expires_at = excluded.expires_at,
         scope = excluded.scope,
         org_id = excluded.org_id,
         updated_at = excluded.updated_at`,
    )
    .run({ ...row, now });
}

export function deleteConnection(userId: string): boolean {
  return cfoDb().prepare("DELETE FROM cfo_connections WHERE user_id = ?").run(userId).changes > 0;
}
import type { ServerResponse } from "node:http";
import type { SessionUser } from "../auth/session";
import {
  CfoOAuthError,
  cfoConfigError,
  completeCfoAuthorization,
  disconnectCfo,
  getCfoStatus,
  startCfoAuthorization,
} from "./oauth";

// HTTP handlers for /api/cfo/*; server.ts resolves the session user first.

function json(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" });
  res.end(JSON.stringify(body));
}

function redirect(res: ServerResponse, location: string): void {
  res.writeHead(302, { location, "cache-control": "no-store" });
  res.end();
}

function notConfigured(res: ServerResponse, reason: string): void {
  json(res, 503, { error: "cfo.ai connection is not configured on this server", reason });
}

// GET /api/cfo/connect -> 302 to the authorization server.
export async function handleCfoConnect(res: ServerResponse, user: SessionUser): Promise<void> {
  const reason = cfoConfigError();
  if (reason) return notConfigured(res, reason);
  try {
    redirect(res, await startCfoAuthorization(user.id));
  } catch (error: unknown) {
    console.error(`cfo.ai connect failed for user ${user.id}: ${(error as Error).message}`);
    redirect(res, "/?cfo=error");
  }
}

// GET /api/cfo/callback?code&state[&iss] -> store tokens, back to the app.
export async function handleCfoCallback(url: URL, res: ServerResponse, user: SessionUser): Promise<void> {
  const reason = cfoConfigError();
  if (reason) return notConfigured(res, reason);
  try {
    await completeCfoAuthorization(user.id, url.searchParams);
    redirect(res, "/?cfo=connected");
  } catch (error: unknown) {
    const code = error instanceof CfoOAuthError ? error.code : "unexpected";
    const message = error instanceof CfoOAuthError ? error.message : "unexpected error";
    console.error(`cfo.ai callback failed for user ${user.id}: ${code} - ${message}`);
    redirect(res, "/?cfo=error");
  }
}

// GET /api/cfo/status -> { configured, connected, expiresAt? } (never tokens).
export function handleCfoStatus(res: ServerResponse, user: SessionUser): void {
  json(res, 200, { configured: cfoConfigError() === null, ...getCfoStatus(user.id) });
}

// POST|DELETE /api/cfo/disconnect -> forget this user's tokens.
export function handleCfoDisconnect(res: ServerResponse, user: SessionUser): void {
  const removed = disconnectCfo(user.id);
  json(res, 200, { connected: false, removed });
}
import { cfoRedirectUri, discoverCfo } from "./oauth";

// One-time Dynamic Client Registration (RFC 7591) of this app as a public cfo.ai OAuth client.
// Prints only the client_id; put it in .env as CFO_OAUTH_CLIENT_ID.

const { authServer } = await discoverCfo();
if (!authServer.registration_endpoint) {
  console.error("cfo.ai authorization server does not advertise a registration_endpoint");
  process.exit(1);
}

const redirectUri = cfoRedirectUri();
const res = await fetch(authServer.registration_endpoint, {
  method: "POST",
  headers: { "content-type": "application/json", accept: "application/json" },
  body: JSON.stringify({
    client_name: "nlhack CFO Agent",
    redirect_uris: [redirectUri],
    grant_types: ["authorization_code", "refresh_token"],
    response_types: ["code"],
    token_endpoint_auth_method: "none",
    scope: "openid profile email offline_access",
  }),
});
const body = (await res.json().catch(() => ({}))) as { client_id?: string; error?: string };
if (!res.ok || !body.client_id) {
  console.error(`Registration failed: HTTP ${res.status}${body.error ? ` (${body.error})` : ""}`);
  process.exit(1);
}

console.log(`Registered public client for redirect URI ${redirectUri}`);
console.log(`Add this line to .env, then restart the server:\n\nCFO_OAUTH_CLIENT_ID=${body.client_id}\n`);
console.log("Re-run this command if APP_URL / BETTER_AUTH_URL changes (the redirect URI is fixed at registration).");

import { MCPClient, type RequireToolApprovalContext } from "@mastra/mcp";

/**
 * Deny by default: a tool skips approval only when GitHub's MCP server annotates it with
 * `readOnlyHint: true` (the server sets it explicitly on every read tool). Write tools, and any
 * tool without that annotation, need human approval.
 */
export function githubToolNeedsApproval({
  annotations,
}: Pick<RequireToolApprovalContext, "annotations">): boolean {
  return annotations?.readOnlyHint !== true;
}

// GitHub's official remote MCP server: https://github.com/github/github-mcp-server
// Auth: a personal access token in GITHUB_PAT. Writes are enabled, but every non-read tool
